// === Tab: mySketch ===
// Based on: https://spalterdigital.com/artworks/untitled-34/

const origWidth = 1024
const aspectRatio = Math.sqrt(2)

const native = { w: origWidth, h: origWidth / aspectRatio }

let l, w, h
let cols, rows

function setup() {
    if (windowWidth < windowHeight * aspectRatio) {
        w = windowWidth; h = w / aspectRatio
    } else {
        h = windowHeight; w = h * aspectRatio
    }

    createCanvas(w, h)

    buffer = createGraphics(native.w, native.h)


    cols = 40
    unitGrid = native.w / cols
    rows = floor(native.h / unitGrid)

    // // noLoop() removed for animationrender(buffer)
}

function draw() {
    if (frameCount != 0 && frameCount % 80 == 0) render(buffer)

    // Draw it in the canvas
    image(buffer, 0, 0, w, h)
}


function render(b) {
    // draw your art on the buffer
    b.background("#FF7100")

    for (let j = 0; j < rows; j++) {
        for (let i = 0; i < cols; i++) {
            let x = i * unitGrid
            let y = j * unitGrid

            let c1, c2
            if (i <= 0.3 * cols)
                c1 = c2 = "#ED1200";
            if (i > 0.3 * cols && i <= 0.7 * cols)
                random() < 0.5 ? c1 = c2 = "#ED1200" : c1 = c2 = "#FFCE00"
            if (i > 0.7 * cols)
                c1 = c2 = "#FFCE00"


            if (i > 0.2 * cols && i <= 0.8 * cols)
                if (random() < 0.2) {
                    c1 = "#ED1200"; c2 = "#FFCE00"
                }
            if ((i > 0.1 * cols && i <= 0.2 * cols) || (i > 0.8 * cols && i <= 0.9 * cols))
                if (random() < 0.1) {
                    c1 = "#ED1200"; c2 = "#FFCE00"
                }
            if (i > 0.2 * cols && i <= 0.8 * cols)
                if (random() < 0.2) {
                    c2 = "#ED1200"; c1 = "#FFCE00"
                }
            if ((i > 0.1 * cols && i <= 0.2 * cols) || (i > 0.8 * cols && i <= 0.9 * cols))
                if (random() < 0.1) {
                    c2 = "#ED1200"; c1 = "#FFCE00"
                }


            if (random() < 0.05) {
                c1 = random(["#ED1200", "#FFCE00"])
                c2 = random(["#ED1200", "#FFCE00"])
            }
            // b.noFill()
            // b.strokeWeight(1)
            // b.stroke(0)
            // b.rect(x, y, unitGrid, unitGrid)
            squareThing(b, x, y, unitGrid, c1, c2)

        }
    }
}

function squareThing(b, x, y, len, insideCol, outsideCol) {
    if (outsideCol == null) outsideCol = insideCol

    let margin = len * 0.1

    b.noFill()
    b.strokeWeight(2)
    // outer
    b.stroke(outsideCol)
    roundedRect(b, x + 1 * margin, y + 1 * margin, len - 2 * margin, len - 2 * margin)
    // inner
    b.stroke(insideCol)
    roundedRect(b, x + 3 * margin, y + 3 * margin, len - 6 * margin, len - 6 * margin)
}

function roundedRect(b, x, y, l1, l2) {
    let off = 0.5
    let coords = [
        [x + randoff(off),      y + randoff(off)],
        [x + l1 + randoff(off), y + randoff(off)],
        [x + l1 + randoff(off), y + l2 + randoff(off)],
        [x + randoff(off),      y + l2 + randoff(off)]
    ]
    // console.log(coords)
    b.strokeCap(ROUND)
    for (let i = 0; i < 4; i++) {
        let j = (i + 1) % 4
        b.line(coords[i][0], coords[i][1], coords[j][0], coords[j][1])
    }
}

function randoff(val) {
    return (random([-1, 1]) * random(val))
}

function windowResized() {
    if (windowWidth < windowHeight * aspectRatio) {
        w = windowWidth; h = w / aspectRatio
    } else {
        h = windowHeight; w = h * aspectRatio
    }

    resizeCanvas(w, h)
}
